            node = ListNode(v)
            if not tail_head:
                tail_head, tail = node, node
            else:
                tail.next = node
                tail = node

    def build_prefix(values, count, shared_head):
        head = None
        t = None
        for v in values[:count]:
            node = ListNode(v)
            if not head:
                head, t = node, node
